from bpmnlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 1700
b = Board('BPMN_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it is for', ul('BPMN draws a business process the way a team and its partners really run it: who does what, in what order, and what is said between organisations.', 'It is stricter than a flowchart. Shapes have fixed meanings, so two people read the same diagram the same way.', 'What a flowchart cannot say: a partner shown only by its name (black-box pool), work in parallel, a task repeated for each item, a deadline that nudges or interrupts, stored data. The Advanced example shows each.')),
 card('Events', ul('A circle. <b>Start:</b> thin green. <b>Intermediate:</b> double amber ring. <b>End:</b> thick rose.', 'A marker inside names the trigger: envelope (message), clock (timer), lightning (error), triangle (signal). An end with an error marker is a failed ending.', 'The label sits below the circle, or above when a line leaves downward. Three words at most.', 'Radius 20 px.')),
 card('Activities', ul('A rounded box 130 × 64, a verb and a noun: <i>Place order</i>, <i>Check stock</i>.', 'A small icon in the top left names the kind: person (user task), gear (service task), filled envelope (send), outlined envelope (receive), hand (manual).', 'A box with a small <b>+</b> at the bottom is a sub-process defined on another page.', 'The tint comes from the lane or pool.')),
 card('Gateways', ul('A diamond 52 px wide. <b>Cross:</b> exclusive, one exit. <b>Plus:</b> parallel, all exits. <b>Circle:</b> inclusive, one or more. <b>Ringed pentagon:</b> wait for the first message.', 'A question above or below the diamond, ending with a question mark. Each exit is labelled <b>yes</b> or <b>no</b>, or with its value.', 'A joining gateway uses the same marker and has no label.')),
 card('Flows', ul('<b>Sequence flow:</b> solid ink, filled head, inside a pool only.', '<b>Message flow:</b> dashed ink with an open circle at the start and a hollow head at the end, between pools only. A short pill names the message.', '<b>Return:</b> dashed slate for a loop back.', 'Routes are orthogonal with at most two bends. A message flow may cross a pool but never an element.')),
 card('Pools and lanes', ul('A <b>pool</b> is one participant, a lane is a role inside it. A vertical coloured band on the left carries the name.', 'Pool 64 px from the left edge, band 36 to 40 px. Lanes at least 200 px high. Pools stacked with 40 px between.', 'Send and receive tasks and message events are the only elements that talk to another pool.')),
 card('Layout', ul('Time runs left to right. Elements that happen at the same moment in different pools share an x position, so message flows run straight up and down.', 'A decision sends its alternative branch into a second row. The happy path stays on the first.', 'Gap between elements 100 px or more where a flow carries a label.', 'About 25 elements per diagram. Longer: use sub-processes.')),
 card('Colour and animation', ul('Tint per pool or lane from the shared palette. Events and gateways keep their own colours.', 'The happy path of one pool is a blue, thick, animated line. One per diagram, not one per pool.', 'Everything else is static. Off when the viewer prefers reduced motion. In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('Plain and illustrated', ul('BPMN has one style. The shapes are the standard, and replacing them with icons would break the notation.', 'Small icons in tasks are part of the standard and are kept.', 'For an audience outside the team, use a flowchart in its illustrated style instead.')),
 card('With other types', ul('A BPMN task is often a flowchart step or a sequence message. Keep the same name.', 'A message flow between pools is usually one arrow of a sequence diagram.', 'Not decided yet: linking a sub-process to its own page.')),
 card('What a plugin can rely on', ul('A pool is: name, tone and lanes. An element is: id, type (event, task, gateway), kind or marker, label, lane and column.', 'A flow is: from, to, type (sequence, message, return), label and a main flag.', 'Layout comes from lanes (rows) and columns. The plugin routes lines and keeps message flows straight.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">BPMN · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions for BPMN diagrams and what a plugin can rely on. Notation shows each shape; the examples show a one-pool and a three-pool process.</div></div>{grid}</div>')
print(save7(b))
